func (m multiAddr) join(f func(net.Addr) string) string {
	switch len(m) {
	case 0:
		return ""
	case 1:
		return f(m[0])
	}
	s := make([]string, len(m))
	for i, a := range m {
		s[i] = f(a)
	}
	return strings.Join(s, ",")
}
